#!/usr/bin/env bash
# Generated by Agent Team Kit 0.20.0. Do not edit: fixes go upstream, settings go in .agent-team/config.sh.
# The merge gate: every PR pastes this script's summary before asking for review. It covers what CI does not
# (device builds, local backend tests, end-to-end flows), so main stays green.
#
#   merge-gate.sh <target>...      run the gates for each target, e.g. merge-gate.sh web backend
#   merge-gate.sh all              run every target in AGENT_TEAM_GATES_ALL
#   merge-gate.sh --list           list the targets .agent-team/config.sh defines
#
# Targets are shell functions named gate_<target> in .agent-team/config.sh. Inside one, call
#   run "<name>" <command...>                 run a step and record PASS or FAIL
#   run "<name>" locked <pool> <command...>   the same, holding a with-lock.sh slot
# Output goes to .merge-gate/<target>-<timestamp>.log; the summary ends with PASS or FAIL lines.
set -uo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
# shellcheck source=lib.sh
. "$here/lib.sh"
at_init
cd "$AT_ROOT" || exit 1

targets() { declare -F | awk '{print $3}' | sed -n 's/^gate_//p'; }
if [ $# -eq 0 ] || [ "$1" = "--list" ] || [ "$1" = "-h" ]; then
  echo "usage: merge-gate.sh <target>... | all | --list" >&2
  echo "targets: $(targets | tr '\n' ' ')" >&2
  [ $# -eq 0 ] && exit 64 || exit 0
fi

mkdir -p .merge-gate
stamp="$(date +%Y%m%d-%H%M%S)"
declare -a results=()
log=""

locked() { local pool="$1"; shift; "$here/with-lock.sh" "$pool" -- "$@"; }
run() { # run <name> <command...>
  local name="$1"; shift
  echo "== $name" | tee -a "$log"
  if "$@" >>"$log" 2>&1; then results+=("PASS $name"); else results+=("FAIL $name ($log)"); fi
}

declare -a want=()
for t in "$@"; do
  if [ "$t" = "all" ]; then
    # shellcheck disable=SC2206
    want+=(${AGENT_TEAM_GATES_ALL:-$(targets | tr '\n' ' ')})
  else
    want+=("$t")
  fi
done

for t in "${want[@]}"; do
  if ! declare -F "gate_$t" >/dev/null; then
    echo "merge-gate: no gate_$t in .agent-team/config.sh (targets: $(targets | tr '\n' ' '))" >&2
    exit 64
  fi
  log=".merge-gate/$t-$stamp.log"
  "gate_$t"
done

echo
echo "merge-gate (${want[*]}) @ $(git rev-parse --short HEAD 2>/dev/null || echo '?') on $(git branch --show-current 2>/dev/null || echo '?')"
if [ ${#results[@]} -eq 0 ]; then echo "  (no steps ran)"; exit 1; fi
printf '  %s\n' "${results[@]}"
for r in "${results[@]}"; do [[ "$r" == FAIL* ]] && exit 1; done
exit 0
